// PRIMARY: beacon-chain/core/peerdas/p2p_interface.go:VerifyDataColumnSidecar (lines 34-52)
func VerifyDataColumnSidecar(sidecar blocks.RODataColumn) error {
	// The sidecar index must be within the valid range.
	numberOfColumns := params.BeaconConfig().NumberOfColumns
	if sidecar.Index >= numberOfColumns { return ErrIndexTooLarge }
	// A sidecar for zero blobs is invalid.
	if len(sidecar.KzgCommitments) == 0 { return ErrNoKzgCommitments }
	// The column length must be equal to the number of commitments/proofs.
	if len(sidecar.Column) != len(sidecar.KzgCommitments) || len(sidecar.Column) != len(sidecar.KzgProofs) {
		return ErrMismatchLength
	}
	return nil
}

// RELATED: beacon-chain/core/peerdas/p2p_interface.go:VerifyDataColumnSidecarInclusionProof (lines 97-125)
func VerifyDataColumnSidecarInclusionProof(sidecar blocks.RODataColumn) error {
	leaves := blocks.LeavesFromCommitments(sidecar.KzgCommitments)
	sparse, err := trie.GenerateTrieFromItems(leaves, fieldparams.LogMaxBlobCommitments)
	hashTreeRoot, err := sparse.HashTreeRoot()
	verified := trie.VerifyMerkleProof(root, hashTreeRoot[:], kzgPosition, sidecar.KzgCommitmentsInclusionProof)
	if !verified { return ErrInvalidInclusionProof }
}

// PRIMARY: beacon-chain/blockchain/kzg/kzg.go:ComputeCellsAndKZGProofs (lines 84-94)
func ComputeCellsAndKZGProofs(blob *Blob) (CellsAndProofs, error) {
	var ckzgBlob ckzg4844.Blob
	copy(ckzgBlob[:], blob[:])
	ckzgCells, ckzgProofs, err := ckzg4844.ComputeCellsAndKZGProofs(&ckzgBlob)
	if err != nil { return CellsAndProofs{}, err }
	return makeCellsAndProofs(ckzgCells[:], ckzgProofs[:])
}

